+				const stub = sinon.stub();
+
+				stub.onFirstCall().rejects(
+					Object.assign(new Error("EMFILE: too many open files"), {
+						code: "EMFILE",
+					}),
+				);
+				stub.onSecondCall().rejects(
+					Object.assign(new Error("ENFILE: file table overflow"), {
+						code: "ENFILE",
+					}),
+				);
+				stub.resolves();
+
+				const { ESLint: localESLint } = proxyquire(
+					"../../../lib/eslint/eslint",
+					{
+						"node:fs/promises": {
+							writeFile: stub,
+						},
+					},
+				);
+
+				await localESLint.outputFixes([
+					{
+						filePath: path.resolve("foo.js"),
+						output: "bar",
+					},
+				]);
+
+				assert.strictEqual(stub.callCount, 3, "Call count was wrong");
+				for (const call of stub.getCalls()) {
+					assert(
+						call.calledWithExactly(path.resolve("foo.js"), "bar"),
+						"Call was incorrect.",
+					);
+				}
+			});
+
+			it("should not retry fs.writeFile() for other errors", async () => {
+				const error = Object.assign(new Error("EACCES"), {
+					code: "EACCES",
+				});
